#include "elit21/aliexpress/transport/AliExpressRequest.h"
#include "elit21/aliexpress/AliExpressMethodNames.h"
namespace elit21::aliexpress::transport {AliExpressRequest::AliExpressRequest(std::string m,std::map<std::string,std::string>p,bool s,std::vector<std::string>r):method_(std::move(m)),parameters_(std::move(p)),requires_session_(s),required_fields_(std::move(r)){}void AliExpressRequest::set(std::string k,std::string v){parameters_[std::move(k)]=std::move(v);}Result<void>AliExpressRequest::validate()const{if(!AliExpressMethodNames::supported(method_))return Result<void>::failure("Unsupported AliExpress method: "+method_);for(const auto&k:required_fields_){auto it=parameters_.find(k);if(it==parameters_.end()||it->second.empty())return Result<void>::failure("Missing AliExpress parameter: "+k);}return Result<void>::success();}}
